# A skill body citation of a shipped reference. The leading class requires an
# alphanumeric first character so documentation placeholders like
# `references/<file>.md` (angle-bracketed) never match and never trip the gate.
CITATION_PATTERN = re.compile(r"references/([A-Za-z0-9][A-Za-z0-9._-]*\.md)")
# Header stamped on every generated Markdown surface this script writes. It is
# a named constant so a test can enumerate templates/ and assert the
# source/generated boundary holds, rather than re-typing the sentence.
DO_NOT_EDIT_MARKER = (
    "<!-- Generated by .github/scripts/generate-skill-surfaces.py; do not edit. -->"
)
GENERATED_REFERENCES_DIR = "generated/references"
HELP_CATALOG_SOURCE = f"{GENERATED_REFERENCES_DIR}/skill-catalog.md"
HELP_CATALOG_PATH = ROOT / HELP_CATALOG_SOURCE
